// Generated by scripts/build_notes.py from content/biology/*.json. Do not edit by hand.
// Attaches authored subsection notes, key terms and practice questions to COURSE_DATA.
(function () {
  if (typeof COURSE_DATA === "undefined") return;
  var NOTES = {};
  COURSE_DATA.chapters.forEach(function (chapter) {
    (chapter.learningOutcomes || []).forEach(function (outcome) {
      var entry = NOTES[outcome.id];
      if (!entry) return;
      outcome.notes = entry.notes;
      outcome.keyTerms = entry.keyTerms.map(function (term) {
        return { term: term.term, definition: term.definition, section: outcome.title };
      });
      outcome.questions = (outcome.questions || []).concat(entry.questions);
      outcome.authored = true;
    });
    var review = (chapter.learningOutcomes || []).find(function (outcome) {
      return outcome.id === chapter.id + "-1";
    });
    if (review && (chapter.learningOutcomes || []).some(function (outcome) { return outcome.authored; })) {
      review.notes = [];
      review.keyTerms = [];
    }
  });
})();
